use gpui_dataset_transformation::{decimate,field_statistics,point_data_to_cell_data,point_data_to_cell_data_validated,FieldStats};
use gpui_mesh::{Association,Cells,DataSet,Field};
use gpui_profiler::AllocProbe;
use std::hint::black_box;
use std::time::Instant;

fn cpu_ns()->u128 {
    let mut stamp=libc::timespec {tv_sec:0,tv_nsec:0};
    // SAFETY: stamp is a valid writable C timespec. The platform clock call
    // writes it synchronously, retains no pointer and is checked for success.
    let result=unsafe {libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID,&mut stamp)};
    assert_eq!(result,0);assert!(stamp.tv_sec>=0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
    stamp.tv_sec as u128*1_000_000_000+stamp.tv_nsec as u128
}

fn value(index:usize,position:[f64;3],n:usize,mode:&str)->f64 {
    match mode {
        "positive"=>((index*37)%255+1) as f64/256.0,
        "separated"=>(position[0]-(n/2) as f64)/8.0,
        "mixed"=>(((index*37)%511) as i32-255) as f64/256.0,
        _=>{
            let hash=(index as u64).wrapping_mul(0x9e3779b97f4a7c15).rotate_left(17);
            let magnitude=f64::from_bits((1023_u64<<52)|(hash&((1_u64<<52)-1)));
            if hash>>63==0 {magnitude} else {-magnitude}
        }
    }
}

fn grid(n:usize,mode:&str)->DataSet {
    let mut data=DataSet::structured_grid("mean",[n;3],[0.0;3],[1.0;3]).unwrap();
    let values=data.positions.iter().enumerate().map(|(i,&p)|value(i,p,n,mode)).collect::<Vec<_>>();
    data.point_data.push(Field::scalar("p",values.clone()));
    data.point_data.push(Field::vector("v",values.iter().map(|&v|[v,v*0.5,v*0.25]).collect::<Vec<_>>()));data
}

enum Output {Data(DataSet),Stats(FieldStats)}

fn measure(n:usize,mode:&str,case:&str,mut run:impl FnMut()->Output,check:impl Fn(&Output)) {
    let warm=black_box(run());check(&warm);drop(warm);
    let mut times=Vec::with_capacity(5);let mut cpus=Vec::with_capacity(5);let mut calls=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let mut allocations=AllocProbe::new();let cpu_start=cpu_ns();let start=Instant::now();let output=black_box(run());let elapsed=start.elapsed().as_nanos();let cpu_elapsed=cpu_ns()-cpu_start;let sample=allocations.sample("reduction");
        times.push(elapsed);cpus.push(cpu_elapsed);calls.push(sample.count);bytes.push(sample.bytes);check(&output);drop(output);
    }
    println!(r#"{{"n":{n},"mode":"{mode}","case":"{case}","times_ns":{times:?},"cpu_times_ns":{cpus:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator_instrumentation":{}}}"#,cfg!(feature="allocations"));
}

fn main() {
    assert!(cpu_ns()>0);
    for n in [8usize,16,24] {for mode in ["positive","separated","mixed","full_precision"] {
        let data=grid(n,mode);let checked=data.validated().unwrap();let scalar=data.point_data[0].as_scalar().unwrap();
        let expected=(0..data.cell_count()).map(|cell|data.cells.cell(cell).unwrap().iter().map(|&node|scalar[node as usize]).sum::<f64>()/8.0).collect::<Vec<_>>();
        let check_scalar=|output:&Output| {
            let Output::Data(out)=output else {panic!()};out.validate().unwrap();
            let values=out.field(Association::Cell,"mean").unwrap().as_scalar().unwrap();assert_eq!(values.len(),expected.len());
            assert!(values.iter().zip(&expected).all(|(a,b)|(a-b).abs()<1e-12));
        };
        measure(n,mode,"p2c_scalar",||Output::Data(point_data_to_cell_data(&data,"p","mean").unwrap()),check_scalar);
        measure(n,mode,"p2c_scalar_validated",||Output::Data(point_data_to_cell_data_validated(checked,"p","mean").unwrap()),check_scalar);
        measure(n,mode,"p2c_vector_validated",||Output::Data(point_data_to_cell_data_validated(checked,"v","mean").unwrap()),|output| {
            let Output::Data(out)=output else {panic!()};out.validate().unwrap();let values=out.field(Association::Cell,"mean").unwrap().as_vector().unwrap();
            for (values,&expected) in values.iter().zip(&expected) {for (&actual,factor) in values.iter().zip([1.0,0.5,0.25]) {assert!((actual-expected*factor).abs()<1e-12);}}
        });
        let expected_mean=scalar.iter().sum::<f64>()/scalar.len() as f64;
        measure(n,mode,"statistics",||Output::Stats(field_statistics(&data,"p",Association::Point).unwrap()),|output| {
            let Output::Stats(stats)=output else {panic!()};assert_eq!(stats.count,scalar.len());assert!((stats.mean-expected_mean).abs()<1e-12);assert!(stats.std_dev.is_finite());
        });
        let half=n/2;let mut expected=vec![0.0;half.pow(3)];
        for (i,p) in data.positions.iter().enumerate() {let id=p[0] as usize/2+half*(p[1] as usize/2+half*(p[2] as usize/2));expected[id]+=scalar[i]/8.0;}
        measure(n,mode,"decimate",||Output::Data(decimate(&data,2.0).unwrap()),|output| {
            let Output::Data(out)=output else {panic!()};out.validate().unwrap();assert_eq!(out.point_count(),half.pow(3));
            let values=out.field(Association::Point,"p").unwrap().as_scalar().unwrap();assert!(values.iter().zip(&expected).all(|(a,b)|(a-b).abs()<1e-12));
        });
    }}
    for mode in ["positive","separated","mixed","full_precision"] {
        let n=48usize;let count=n.pow(3);let values=(0..count).map(|i|value(i,[(i%n) as f64,0.0,0.0],n,mode)).collect::<Vec<_>>();let expected=values.iter().sum::<f64>()/count as f64;
        let data=DataSet::new("statistics",vec![[0.0;3];count],Cells::from_cells(&[])).with_field(Field::scalar("p",values));
        measure(n,mode,"statistics",||Output::Stats(field_statistics(&data,"p",Association::Point).unwrap()),|output| {
            let Output::Stats(stats)=output else {panic!()};assert_eq!(stats.count,count);assert!((stats.mean-expected).abs()<1e-12);assert!(stats.std_dev.is_finite());
        });
    }
}
